from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict

SYNTHETIC_DATA_DISCLAIMER_MODEL = (
    "These predictions were generated by models trained on this project's SYNTHETIC "
    "highway-project dataset (see docs/SYNTHETIC_DATA_METHODOLOGY.md). They do NOT "
    "represent real NHAI predictive accuracy, production readiness, or government "
    "validation -- this is a prototype decision-support system inspired by highway "
    "infrastructure project monitoring, not an official NHAI system."
)

SYNTHETIC_DATA_DISCLAIMER_ACTUAL = (
    "These are recorded final outcomes from this project's SYNTHETIC dataset "
    "trajectory (see docs/SYNTHETIC_DATA_METHODOLOGY.md), not real NHAI data."
)

TERMINAL_EXPLANATION = (
    "This snapshot is terminal; recorded final outcomes are returned instead of "
    "model predictions."
)

NON_TERMINAL_EXPLANATION = (
    "This snapshot is non-terminal; each task's Phase 5 recommended model was used "
    "to generate a prediction from this snapshot's permitted predictor features."
)

# Phase 17B: returned instead of a raw 422 when a snapshot exists but a
# full model input row genuinely cannot be built from it yet (e.g. a
# newly created project with too little monthly history). Never a
# fabricated or guessed prediction -- prediction_status="insufficient_data"
# and every task result below is left empty.
INSUFFICIENT_DATA_EXPLANATION = (
    "There is not yet enough recorded data for this project at this reporting month "
    "to build the full set of model input features. No prediction has been "
    "generated -- add further monthly progress updates, or select a reporting month "
    "that already has a complete snapshot."
)


class SignificantDelayResult(BaseModel):
    model_config = ConfigDict(protected_namespaces=())

    task: Literal["significant_delay"] = "significant_delay"
    model_used: str | None = None
    predicted_class: int | None = None
    probability_of_significant_delay: float | None = None
    actual_value: int | None = None


class FinalDelayDaysResult(BaseModel):
    model_config = ConfigDict(protected_namespaces=())

    task: Literal["final_delay_days"] = "final_delay_days"
    model_used: str | None = None
    predicted_final_delay_days: float | None = None
    actual_value: int | None = None


class CostOverrunResult(BaseModel):
    model_config = ConfigDict(protected_namespaces=())

    task: Literal["cost_overrun"] = "cost_overrun"
    model_used: str | None = None
    predicted_class: int | None = None
    probability_of_cost_overrun: float | None = None
    actual_value: int | None = None


class FinalCostOverrunPctResult(BaseModel):
    model_config = ConfigDict(protected_namespaces=())

    task: Literal["final_cost_overrun_pct"] = "final_cost_overrun_pct"
    model_used: str | None = None
    predicted_final_cost_overrun_pct: float | None = None
    actual_value: float | None = None


class PredictionResponse(BaseModel):
    project_id: str
    reporting_month: str
    is_terminal_snapshot: bool
    prediction_status: Literal["actual_outcome", "model_prediction", "insufficient_data"]
    is_model_prediction: bool
    explanation: str
    synthetic_data_disclaimer: str

    significant_delay: SignificantDelayResult
    final_delay_days: FinalDelayDaysResult
    cost_overrun: CostOverrunResult
    final_cost_overrun_pct: FinalCostOverrunPctResult
